def money(key, label, default=0):
    return (key, label, 'money', default, 0, 100000000)

def count(key, label, default, maximum=1200):
    return (key, label, 'count', default, 0, maximum)

def rate(key='rate', label='연 유효수익률 가정 (%)', default=0.0, minimum=-20.0):
    return (key, label, 'rate', default, minimum, 30.0)

